int checks=0;
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);++checks;}
void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QTest::qWait(20);}
void valid(const Document& d){validate(d);check(decode(encode(d))==d,"Independent full caller native-valid BEFORE Window");}
void same(const Session& a,const Session& b){check(a.document()==b.document()&&encode(a.document())==encode(b.document())&&a.preview_document()==b.preview_document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation(),"Entire caller Session/native/History/preview/revision/generation unchanged");}
void write(const QString& path,const Document& d){QFile f(path);const auto b=encode(d);check(f.open(QIODevice::WriteOnly|QIODevice::NewOnly)&&f.write(b.data(),b.size())==static_cast<qint64>(b.size()),"Immutable actual or independent native retained once");}
QByteArray read(const QString& path){QFile f(path);check(f.open(QIODevice::ReadOnly),"Owned native bytes readable");return f.readAll();}
template<class T>T* control(Window& w,const QString& name){for(auto* c:w.findChildren<T*>(name))if(c->isVisible())return c;throw std::runtime_error("Original visible source producer missing");}
void reveal(QWidget* c){QPointer<QWidget> alive=c;for(auto* p=c->parentWidget();p;p=p->parentWidget())if(auto* s=qobject_cast<QScrollArea*>(p))s->ensureWidgetVisible(c);events();check(alive&&alive->isVisible()&&alive->isEnabled(),"Original source producer survives reveal and is enabled");}

Document fixture(){auto d=empty_document("instance-override-context","comp","art");auto& board=d.compositions.front().artboards.front();board.width=640;board.height=480;Object shape;shape.id="shape";shape.name="Child A";shape.source=default_primitive("shape-source","nect.shape.rectangle");shape.source->parameters.at("width").literal=80;shape.source->parameters.at("height").literal=60;shape.source->parameters.at("center_x").literal=320;shape.source->parameters.at("center_y").literal=240;auto fill=default_operation("shape-fill","nect.paint.fill");fill.parameters.at("r").literal=1;fill.parameters.at("g").literal=0;fill.parameters.at("b").literal=0;shape.stack={fill};auto peer=shape;peer.id="peer";peer.name="Child B";peer.source->id="peer-source";peer.source->parameters.at("width").literal=60;peer.source->parameters.at("height").literal=80;peer.source->parameters.at("center_x").literal=180;peer.stack.front().id="peer-fill";peer.stack.front().parameters.at("r").literal=0;peer.stack.front().parameters.at("b").literal=1;Object group;group.id="group";group.name="Original source";group.kind=Kind::group;group.children={shape.id};Object source;source.id="defined-group";source.name="Defined source";source.kind=Kind::group;source.children={peer.id};d.objects.emplace(shape.id,shape);d.objects.emplace(peer.id,peer);d.objects.emplace(group.id,group);d.objects.emplace(source.id,source);d.compositions.front().roots={group.id,source.id};d.definitions.emplace("definition",Definition{"definition","Existing Definition","defined-group"});auto outside=d.objects.at("shape");outside.id="outside";outside.name="Unaffected source";outside.source->id="outside-source";outside.stack.front().id="outside-fill";d.objects.emplace(outside.id,outside);d.objects.at("group").children={outside.id};d.objects.at("defined-group").children={"shape","peer"};d.objects.at("shape").name="Twin";d.objects.at("peer").name="Twin";Object instance;instance.id="instance";instance.name="Original instance";instance.kind=Kind::instance;instance.instance=DefinitionInstance{"definition",{}};instance.instance->overrides={{{"peer","","generator.height"},20},{{"shape","","generator.height"},40}};auto sibling=instance;sibling.id="sibling";sibling.name="Sibling instance";sibling.instance->overrides.at({"peer","","generator.height"})=60;sibling.instance->overrides.at({"shape","","generator.height"})=50;d.objects.emplace(instance.id,instance);d.objects.emplace(sibling.id,sibling);d.compositions.front().roots.push_back(instance.id);d.compositions.front().roots.push_back(sibling.id);return d;}
void flow(const QString& root,int mode){const bool reset=mode>=5,success=mode==4||mode==6,foreign_case=mode==0||mode==5;auto initial=fixture();valid(initial);auto current=initial;current.objects.at("instance").name="Current instance";valid(current);Session base(initial);base.apply({Rename{"instance","Current instance"}},0);check(base.document()==current&&base.revision()==1,"Whole original source hierarchy/native/History BEFORE Window");auto foreign_initial=initial;foreign_initial.id="foreign-definition-document";foreign_initial.objects.at("shape").source->parameters.at("height").literal=90;foreign_initial.objects.at("peer").source->parameters.at("height").literal=70;foreign_initial.objects.at("instance").instance->overrides.at({"peer","","generator.height"})=22;foreign_initial.objects.at("instance").instance->overrides.at({"shape","","generator.height"})=44;valid(foreign_initial);auto foreign_current=foreign_initial;foreign_current.objects.at("instance").name="Current instance";valid(foreign_current);Session foreign(foreign_initial);foreign.apply({Rename{"instance","Current instance"}},0);check(foreign.document()==foreign_current&&foreign.revision()==base.revision()&&foreign.gesture_generation()==base.gesture_generation(),"Independent whole foreign source hierarchies with colliding Group/Definition IDs and equal counters BEFORE Window");auto concurrent=base;concurrent.apply({Rename{"instance","Concurrent instance"}},1);auto concurrent_doc=current;concurrent_doc.objects.at("instance").name="Concurrent instance";valid(concurrent_doc);check(concurrent.document()==concurrent_doc,"Full concurrent original source caller BEFORE Window");auto busy=base;busy.begin_gesture(1);busy.update_gesture({Set{{"shape","","generator.height"},90}});auto preview=current;preview.objects.at("shape").source->parameters.at("height").literal=90;valid(preview);check(busy.document()==current&&busy.preview_document()==preview,"Whole independent source-child preview BEFORE Window");const Ref target=reset?Ref{"shape","","generator.height"}:Ref{"peer","","generator.height"};auto transformed=current;if(reset)transformed.objects.at("instance").instance->overrides.erase(target);else transformed.objects.at("instance").instance->overrides.at(target)=50;valid(transformed);auto committed=base;if(reset)committed.apply({DefinitionCommand{ResetInstanceOverride{"instance",target}}},1);else committed.apply({DefinitionCommand{SetInstanceOverride{"instance",target,50}}},1);check(committed.document()==transformed,"Independent whole local override delta preserves both source subtrees/sibling Instance and matches typed command BEFORE Window");auto history=committed;history.undo(2);check(history.document()==current,"Entire source hierarchy Undo BEFORE Window");history.redo(3);check(history.document()==transformed&&history.history()==committed.history(),"One History/full Redo BEFORE Window");auto expected=base;if(foreign_case)expected=foreign;else if(mode==2)expected=concurrent;else if(mode==3)expected=busy;else if(success)expected=committed;const auto prefix=root+"/mode-"+QString::number(mode);write(prefix+"-expected.nect",expected.document());write(prefix+"-expected-preview.nect",expected.preview_document());
QSettings settings(prefix+"-settings.ini",QSettings::IniFormat);settings.setFallbacksEnabled(false);Window w(prefix+"-recovery",std::make_unique<FolderLibrary>(settings,FolderLibrary::PersistOverride{},FolderLibrary::ReadbackOverride{},prefix+"-assets"),&settings);w.host.session=base;w.host.edited();w.resize(1400,1050);w.show();events();w.canvas->set_active_artboard("comp","art",false);w.canvas->set_selection("instance","");events();auto* actor=w.findChild<QAction*>(reset?"reset-instance-override":"set-instance-override");check(actor&&actor->isEnabled(),"Original Definitions create/place action enabled");const auto original_host=w.host.session_id;QString callback_error,chosen_text;int stages=0,chosen_index=-1;QTimer::singleShot(0,&w,[&]{try{auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget());check(dialog&&dialog->windowTitle()==(reset?"Reset Instance override":"Set Instance override"),"Original supported Instance Set/Reset modal exact");++stages;if(reset){auto* d=qobject_cast<QInputDialog*>(dialog);auto* combo=d?d->findChild<QComboBox*>():nullptr;check(combo&&combo->count()==2,"Original two retained override Refs, independently ordered peer then shape BEFORE Window");combo->setCurrentIndex(1);chosen_index=combo->currentIndex();chosen_text=combo->currentText();check(chosen_index==1&&chosen_text.contains("generator.height"),"Original second source Ref choice captured; same-name ambiguity must never retarget");}else{auto* source=dialog->findChild<QComboBox*>("set-instance-override-source");auto* property=dialog->findChild<QComboBox*>("set-instance-override-property");auto* scalar=dialog->findChild<QDoubleSpinBox*>("set-instance-override-value");check(source&&property&&scalar,"Original supported local override controls exist");const auto index=source->findData("peer");check(index>=0,"Original exact source object ID entry");source->setCurrentIndex(index);events();const auto field=property->findData("generator.height");check(field>=0,"Original supported source Scalar Ref entry");property->setCurrentIndex(field);events();check(scalar->value()==20,"Original local source value captured from selected Instance");scalar->setValue(50);}if(foreign_case)w.host.session=foreign;else if(mode==1)w.host.session_id+="-changed";else if(mode==2)w.host.session=concurrent;else if(mode==3)w.host.session=busy;check(dialog->grab().save(prefix+"-dialog.png"),"Actual original local override modal BEFORE acceptance");if(reset)dialog->accept();else{auto* buttons=dialog->findChild<QDialogButtonBox*>();check(buttons&&buttons->button(QDialogButtonBox::Apply),"Original Set Apply producer");buttons->button(QDialogButtonBox::Apply)->click();}}catch(const std::exception& e){callback_error=QString::fromUtf8(e.what());if(auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget()))dialog->reject();}});actor->trigger();events();check(callback_error.isEmpty()&&stages==1,"Original create/place modal completes without fixture exception");const auto observed=w.host.session;const auto status=w.statusBar()->currentMessage();write(prefix+"-observed.nect",observed.document());write(prefix+"-observed-preview.nect",observed.preview_document());const auto actual=observed.document(),actual_preview=observed.preview_document();write(prefix+"-normalized.nect",actual);write(prefix+"-normalized-preview.nect",actual_preview);check(w.grab().save(prefix+"-window.png"),"Actual original create/place result BEFORE Save");QJsonObject v{{"mode",mode},{"status",status},{"chosen_index",chosen_index},{"chosen_text",chosen_text},{"document_equal",actual==expected.document()},{"preview_equal",actual_preview==expected.preview_document()},{"history_equal",observed.history()==expected.history()},{"revision",qint64(observed.revision())},{"gesture_active",observed.gesture_active()},{"gesture_generation",qint64(observed.gesture_generation())},{"caller_identity_preserved",mode!=3||observed.gesture_identity()==busy.gesture_identity()},{"host_equal",mode==1?w.host.session_id!=original_host:w.host.session_id==original_host},{"view_equal",w.canvas->selected_object=="instance"&&w.canvas->selected_point.empty()&&w.canvas->active_composition()=="comp"&&w.canvas->active_artboard()=="art"},{"save_intent",mode!=3}};QFile metadata(prefix+"-producer.json");check(metadata.open(QIODevice::WriteOnly|QIODevice::NewOnly),"Immutable full source/native/History/view readback BEFORE Save");metadata.write(QJsonDocument(v).toJson());metadata.close();same(observed,expected);check(v["view_equal"].toBool()&&v["host_equal"].toBool()&&v["caller_identity_preserved"].toBool(),"Whole caller view/gesture identity preserved or current new Instance selected");if(mode==0||mode==1||mode==2||mode==5)check(status.startsWith("REVISION_CONFLICT:"),"Original Instance source/Doc/Host/revision refusal explicit");if(mode==3)check(status.startsWith("GESTURE_ACTIVE:"),"Busy source caller refusal explicit");if(success){check(status.startsWith(reset?"Local override reset":"Local Instance override set"),"Current source creation/placement success explicit");w.host.session.undo(2);check(w.host.session.document()==current,"Actual accepted hierarchy whole Undo");w.host.session.redo(3);check(w.host.session.document()==transformed,"Actual accepted hierarchy whole Redo");w.host.session=observed;}if(mode!=3){w.host.save(prefix+"-saved.nect");w.host.flush();events();same(w.host.session,expected);check(decode(read(prefix+"-saved.nect").toStdString())==expected.document()&&QFile::copy(prefix+"-saved.nect",prefix+"-snapshot.nect"),"Whole raw source hierarchy native Save/snapshot with exact sole new-ID bijection");}w.close();events();}
